package com.stacklab.service;
import com.stacklab.dto.ApiDtos.*;import com.stacklab.entity.*;import com.stacklab.exception.*;import com.stacklab.repository.*;import org.springframework.data.domain.*;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class UserService{private final UserRepository users;private final PasswordEncoder encoder;private final ActivityRepository activities;private final CurrentUserService current;public UserService(UserRepository u,PasswordEncoder e,ActivityRepository a,CurrentUserService c){users=u;encoder=e;activities=a;current=c;}
 @Transactional public UserView create(UserCreate r){if(users.existsByEmailIgnoreCase(r.email()))throw new ConflictException("Email is already in use");AppUser created=users.save(new AppUser(r.name(),r.email(),encoder.encode(r.password()),r.role()));activities.save(new ActivityLog(null,null,current.get(),"USER_CREATED",null,null,created.getEmail()));return UserView.of(created);}
 public Page<UserView> list(String q,Pageable p){return users.findAll((root,query,cb)->q==null||q.isBlank()?cb.conjunction():cb.or(cb.like(cb.lower(root.get("name")),"%"+q.toLowerCase()+"%"),cb.like(cb.lower(root.get("email")),"%"+q.toLowerCase()+"%")),p).map(UserView::of);}
 public UserView get(Long id){return UserView.of(users.findById(id).orElseThrow(()->new NotFoundException("User not found")));}
 @Transactional public UserView update(Long id,UserUpdate r){AppUser u=users.findById(id).orElseThrow(()->new NotFoundException("User not found"));if(r.email()!=null&&!r.email().equalsIgnoreCase(u.getEmail())&&users.existsByEmailIgnoreCase(r.email()))throw new com.stacklab.exception.ConflictException("Email is already in use");String oldEmail=u.getEmail();u.update(r.name(),r.email(),r.role(),r.active());activities.save(new ActivityLog(null,null,current.get(),"USER_UPDATED","email",oldEmail,u.getEmail()));return UserView.of(u);}
 @Transactional public void deactivate(Long id){AppUser u=users.findById(id).orElseThrow(()->new NotFoundException("User not found"));u.deactivate();activities.save(new ActivityLog(null,null,current.get(),"USER_DEACTIVATED",null,null,u.getEmail()));}
}
